"""Sasongko 2025 source-specific author transcription; no independent approval."""
TITLE='High-Temperature Photoluminescence Enhancement up to 350 K of Monophase α-FAPbI3 Quantum Dots Synthesized via Tailored Hot Injection'
AUTHORS=['Nurwarrohman Andre Sasongko','Safira Arta Paramita','Jaeseong Heo','Eugene Park','Sebastian E. Reyes-Lillo','Joonkyung Jang','Myeongkee Park']
# id, role, page, locator, title, claim, scope, quantities(meaning, raw, unit), flags, claim class
FACTS=[
('identity','main',1,'Title, abstract, DOI and dates','Source identity','This 2025 study optimizes ligand ratio, washing solvent ratio and growth temperature for FAPbI3 QDs, then investigates temperature-dependent PL and Raman. Matching SI supplies the experimental procedures.','source',[],'','source_identity'),
('materials','si',3,'Materials','Reagent supply','All chemicals are used without further purification. PbI2 has no printed supplier/purity. Formamidine acetate 99%, OA 99%, OAm 70%, toluene 99.8% anhydrous, acetonitrile 99.8% anhydrous and hexane 95% anhydrous are from Sigma-Aldrich; 1-octadecene >90% is from TCI. No isomer or water-content assay is supplied.','purchased reagents',[('formamidine acetate purity','99','%'),('ODE purity','>90','%'),('OA purity','99','%'),('OAm purity','70','%'),('toluene purity','99.8','%'),('acetonitrile purity','99.8','%'),('hexane purity','95','%')],'G1','reported_material'),
('fa-charge','si',3,'Preparation of FA-Oleate','FA precursor charge','Mix 0.1042 g formamidine acetate salt (HN=CHNH2·CH3COOH) with 0.8 mL OA and 3.2 mL ODE. This is the complete prepared FA-oleate formulation, distinct from the 0.51 mL injection aliquot. A final stock volume or molarity is not reported.','FA-oleate preparation',[('formamidine acetate charge','0.1042','g'),('stock OA charge','0.8','mL'),('stock ODE charge','3.2','mL')],'G2','reported_operation'),
('fa-vacuum','si',3,'Preparation of FA-Oleate','FA precursor vacuum hold','Hold the FA precursor mixture at 60 °C for 30 min under vacuum. Pressure, vessel, stirring speed and heating ramp are not given.','FA-oleate preparation',[('hold temperature','60','degC'),('hold duration','30','min')],'G2','reported_operation'),
('fa-hot','si',3,'Preparation of FA-Oleate','FA precursor nitrogen hold','Raise the temperature to 135 °C and hold for 2 h under N2. The named FA-oleate stock is not assigned a measured solution coordination structure or final concentration.','FA-oleate preparation',[('hold temperature','135','degC'),('hold duration','2','h')],'G2','reported_operation'),
('qd-charge','si',3,'Synthesis of FAPbI3 QDs','Lead precursor charge and degassing','All synthesis experiments are described as under N2. Degas 0.075 mmol PbI2 in 2.5 mL ODE at 60 °C for 30 min. Unlike the FA preparation, this sentence does not specify vacuum pressure or explicitly name a vacuum atmosphere for the degassing stage.','QD precursor preparation',[('PbI2 charge','0.075','mmol'),('ODE charge','2.5','mL'),('degassing temperature','60','degC'),('degassing duration','30','min')],'G2','reported_operation'),
('qd-preheat','si',3,'Synthesis of FAPbI3 QDs','Lead precursor preheat','Increase the precursor solution temperature to 135 °C for 30 min. No ramp rate is reported.','QD precursor preparation',[('preheat temperature','135','degC'),('preheat duration','30','min')],'G2','reported_operation'),
('qd-ligands','si',3,'Synthesis of FAPbI3 QDs','Sequential ligand additions','At 135 °C inject the selected OA volume of 0.4, 0.6 or 0.8 mL, then inject 0.2 mL OAm. These pairs correspond to source OAm:OA volume ratios 1:2, 1:3 and 1:4. They are alternative condition choices, not three successive OA charges.','ligand-ratio variants',[('OA low volume','0.4','mL'),('OA middle volume','0.6','mL'),('OA high volume','0.8','mL'),('OAm volume','0.2','mL'),('addition temperature','135','degC')],'G2','reported_operation'),
('qd-equilibrate','si',3,'Synthesis of FAPbI3 QDs','Selected reaction-temperature hold','Cool the PbI2 precursor mixture to the selected reaction temperature, 25, 50 or 100 °C, for 30 min. The preceding 135 °C precursor treatment is not the QD growth temperature.','growth-temperature variants',[('temperature low','25','degC'),('temperature middle','50','degC'),('temperature high','100','degC'),('selected-temperature hold','30','min')],'G2','reported_operation'),
('qd-inject','si',3,'Synthesis of FAPbI3 QDs','FA injection and immediate cooling','At the selected temperature inject 0.51 mL of the prepared FA precursor and promptly cool to room temperature. A numerical room temperature, post-injection growth dwell, injection rate and cooling rate are unreported.','QD formation',[('FA precursor aliquot','0.51','mL')],'G2','reported_operation'),
('wash-formulation','si',3,'Synthesis of FAPbI3 QDs, workup','Washing formulation','Wash the crude solution with the selected acetonitrile:toluene ratio 1:1, 1:10 or 1:20 by volume. Absolute solvent amounts and number of washing repetitions are not supplied; the three ratios are alternative purification conditions.','purification variants',[('acetonitrile parts','1','volume_parts'),('toluene low parts','1','volume_parts'),('toluene middle parts','10','volume_parts'),('toluene high parts','20','volume_parts')],'G2','reported_operation'),
('wash-spin','si',3,'Workup first centrifugation','First retained fraction','Centrifuge the washed crude dispersion at 12000 rpm for 5 min and retain the resulting precipitate. Rotor radius/RCF and centrifuge temperature are unspecified; do not replace rpm with a calculated force.','first workup separation',[('rotation rate','12000','rpm'),('duration','5','min')],'G2','reported_operation'),
('redisperse','si',3,'Workup redispersion','Hexane redispersion','Redisperse the retained precipitate in hexane. The hexane amount and dispersion concentration are not reported.','retained first precipitate',[],'G2','reported_operation'),
('clarify-spin','si',3,'Workup second centrifugation','Final retained supernatant','Centrifuge the redispersed material at 6000 rpm for 5 min and store the supernatant for characterization. The second precipitate is not the stated retained product. Storage duration, temperature, concentration and vessel are unreported.','final supernatant',[('rotation rate','6000','rpm'),('duration','5','min')],'G2 G3','reported_operation'),
('ligand-design','main',2,'Figure 1 caption and Results','Ligand-ratio comparison scope','Figure 1 compares OAm:OA 1:2, 1:3 and 1:4 at 100 °C, each with acetonitrile:toluene 1:20 purification. The study does not establish a full Cartesian matrix over all three varied parameters.','Figure 1 ligand family',[('growth temperature','100','degC'),('wash acetonitrile parts','1','volume_parts'),('wash toluene parts','20','volume_parts')],'G3','reported_experimental_design'),
('ligand-xrd','main',2,'Figure 1a and text','Ligand-dependent diffraction','The 1:3 sample has the narrowest labeled (001)/(002) diffraction widths. Figure 1a reports 0.56/0.60 for 1:2, 0.37/0.44 for 1:3 and 0.71/0.78 for 1:4. These are source peak widths, not a numerical lattice refinement or a measured ligand geometry.','ligand XRD',[],'G4','reported_structure'),
('ligand-optical','main',2,'Figure 1b,c and text','Ligand-dependent PL','Increasing OA shifts the PL peak to lower energy. The average PL lifetimes are approximately 95, 150 and 70 ns for OAm:OA 1:2, 1:3 and 1:4, respectively. The relation to size, passivation and nonradiative recombination is the authors’ interpretation.','ligand optical comparison',[('lifetime 1:2','~95','ns'),('lifetime 1:3','~150','ns'),('lifetime 1:4','~70','ns')],'G3','reported_measurement_and_interpretation'),
('ligand-mechanism','main',2,'Ligand-ratio discussion','Ligand mechanism interpretation','The authors associate excess OAm with protonated OAm+ replacing FA+ and disrupting the lattice, insufficient OA with reduced FA-oleate formation, and excess OA with hindered growth and dissolution in washing solvent. These are mechanistic explanations, not measured occupancies, solution structures or reaction stoichiometries.','author ligand model',[],'G4','author_interpretation'),
('wash-design','main',3,'Figure 2 caption','Purification-ratio comparison scope','Figure 2 compares acetonitrile:toluene 1:1, 1:10 and 1:20 at a fixed 100 °C growth temperature and OAm:OA 1:3.','Figure 2 washing family',[('growth temperature','100','degC')],'G3','reported_experimental_design'),
('wash-results','main',3,'Figure 2 and Results','Washing-dependent crystallinity and lifetime','The (001)/(002) widths are 0.48/0.53, 0.42/0.48 and 0.37/0.44 for wash ratios 1:1, 1:10 and 1:20. Average lifetimes are 80, 135 and 150 ns, respectively. The authors attribute the trend to ligand removal, crystal quality and reduced surface trapping.','wash series',[('lifetime 1:1','80','ns'),('lifetime 1:10','135','ns'),('lifetime 1:20','150','ns')],'G3','reported_measurement_and_interpretation'),
('wash-limit','main',3,'Purification discussion','Purification limitation','The paper suggests toluene contents greater than the 1:20 acetonitrile:toluene condition could partly dissolve QDs and reduce yield/uniformity. No quantified isolated mass yield or additional measured ratio beyond the stated series is supplied.','author workup interpretation',[],'G3','author_interpretation'),
('temperature-design','main',3,'Figure 3 caption p4 and text','Growth-temperature comparison scope','Figure 3 compares growth at 25, 50 and 100 °C, fixing OAm:OA at 1:3 and acetonitrile:toluene at 1:20. These are synthesis temperatures, distinct from the later 80–430 K optical measurement temperatures.','Figure 3 growth family',[],'G3','reported_experimental_design'),
('temperature-phase','main',3,'Figure 3a p4 and text','Temperature-dependent phase assignments','At 25 °C the source identifies α-FAPbI3 together with δ-FAPbI3 and PbI2. At 50 °C it lists (001), (002), (012), (022) and (003) α-FAPbI3 reflections. At 100 °C it emphasizes (001), (002) and (003), interpreted as improved preferred orientation and crystallinity. No current particle coordinates or quantitative phase fractions are supplied.','growth-temperature diffraction',[],'G4','reported_structure_and_interpretation'),
('temperature-lifetimes','main',3,'Figure 3b p4 and text','Growth-temperature lifetimes','Average PL lifetimes are approximately 60, 70 and 150 ns for synthesis at 25, 50 and 100 °C. Prior reports with 20–100 ns and typical 80 °C syntheses are literature comparisons, not additional current routes.','growth-temperature PL',[('25C lifetime','~60','ns'),('50C lifetime','~70','ns'),('100C lifetime','~150','ns'),('cited lifetime interval','20–100','ns'),('cited typical synthesis temperature','~80','degC')],'G3','reported_measurement_and_literature_context'),
('temperature-size','main',3,'Figure 3d–i p4 and text','TEM size distributions','The source reports average dimensions of 7.6 ± 2.4, 9.5 ± 1.6 and 10.4 ± 1.1 nm at 25, 50 and 100 °C. Histogram FWHM values are 5.7, 3.7 and 2.7 nm. The ± statistic is not explicitly defined. All three TEM panels have 20 nm bars; no count of measured particles is supplied.','growth-temperature TEM',[],'G3 G4','reported_measurement'),
('fringe','main',4,'Figure 3f inset and caption','Local lattice-fringe annotation','The 100 °C TEM inset labels d(002) = 6.38 Å. Preserve the printed index and distance. The main p6 cubic reference cell a = 6.36 Å would not yield that (002) spacing under the standard cubic d-hkl relation; this source tension is not resolved by reindexing the image.','100C local TEM',[('printed d(002)','6.38','angstrom')],'C4 G4','reported_structure'),
('xrd-method','si',4,'Analysis and Characterization','Powder XRD acquisition','Use the X-pert3-Powder X-ray diffractometer (PANalytical). Radiation, scan step/range, sample mounting and instrumental broadening correction are not supplied.','XRD acquisition',[],'G5','reported_acquisition'),
('trpl-method','si',4,'Analysis and Characterization','Lifetime acquisition and fitting','Use a HORIBA Fluorolog-QM with 404 nm excitation and 4 ns IRF. Fit decay curves with a triple-exponential function and calculate the stated intensity-weighted average using the printed equation (2). Individual amplitudes, component lifetimes and fit errors are absent.','TRPL acquisition',[('excitation wavelength','404','nm'),('IRF','4','ns'),('exponential components','3','count')],'C5 G5','reported_acquisition_and_analysis'),
('tem-method','si',4,'Analysis and Characterization','Microscopy acquisition','Use FE TEM JEM-F200 (JEOL), with ImageJ for size distributions. Voltage, grid/support, deposition procedure and raw particle measurements are unspecified. No SAED or atomic-coordinate dataset is supplied.','TEM acquisition',[],'G5','reported_acquisition'),
('temperature-method','si',4,'Analysis and Characterization','Temperature-dependent spectroscopy','Measure temperature-dependent Raman and PL with a Horiba LabRam, controlling temperature using Linkam LNP96_S and LTS 420, printed as a hostage module. Laser power, sample physical form, mounting, temperature ramp/equilibration and atmosphere are not specified. N2 synthesis is not silently inherited by measurement.','variable-temperature PL/Raman',[],'C5 G5','reported_acquisition'),
('pl-temperature-scan','main',4,'Figures 4 and 5; Results','Variable-temperature PL','Measure PL from 80 to 430 K. Fit spectra with Lorentzian functions and extract PL peak energy, FWHM and intensity. The observed trend changes are assigned to γ-tetragonal-1 → β-tetragonal-2 at 140 K and β → α-cubic at 250 K. These are source interpretations supported by optical/Raman trends, not variable-temperature coordinate refinements on the QDs.','temperature-dependent PL',[('PL scan interval','80–430','K'),('gamma-beta transition','140','K'),('beta-alpha transition','250','K')],'G3 G4 G5','reported_measurement_and_interpretation'),
('pl-gamma','main',4,'Figure 5 discussion','Gamma-regime fitted slopes','Between 80 and 140 K the PL energy slope is −7.9 × 10−5 eV/K and the FWHM slope is 4.01 × 10−4 eV/K. The authors attribute the redshift and decreasing intensity to electron-phonon coupling and thermally activated nonradiative loss. No independent refitting is performed.','gamma optical fit',[('energy slope','-7.9e-5','eV/K'),('FWHM slope','4.01e-4','eV/K')],'G5','source_calculation_and_interpretation'),
('pl-beta','main',4,'Figure 5 discussion','Beta-regime fitted slopes','Above 140 K the energy slope is 4.32 × 10−4 eV/K and FWHM slope 2.29 × 10−4 eV/K, assigned to the β regime before 250 K. Intensity continues to decline at a reduced rate. Thermal expansion and dynamic framework displacement are proposed causes.','beta optical fit',[('energy slope','4.32e-4','eV/K'),('FWHM slope','2.29e-4','eV/K')],'G5','source_calculation_and_interpretation'),
('pl-alpha','main',5,'Figure 5 discussion','Alpha-regime enhancement','At 250 K the energy slope changes to 3.97 × 10−4 eV/K and FWHM slope to 1.69 × 10−4 eV/K. PL intensity increases up to 350 K. The source attributes this to improved cubic order, lower defect density and facet-dependent recombination; it does not measure carrier mobility directly.','alpha 250–350K optical regime',[('energy slope','3.97e-4','eV/K'),('FWHM slope','1.69e-4','eV/K'),('enhancement upper temperature','350','K')],'G4 G5','source_calculation_and_interpretation'),
('pl-overheat','main',6,'Figure 5 discussion','Higher-temperature intensity decline','Above 350 K the energy slope increases to 7.26 × 10−4 eV/K and the FWHM slope to 3.35 × 10−4 eV/K, while PL intensity decreases. Excessive expansion, hot-phonon interactions and disorder are proposed; no new phase distinct from the α regime is assigned.','alpha above350K optical regime',[('energy slope','7.26e-4','eV/K'),('FWHM slope','3.35e-4','eV/K'),('decline threshold','>350','K')],'G4 G5','source_calculation_and_interpretation'),
('raman-range','si',6,'Raman discussion and S2 caption p5','Raman acquisition range limitation','Raman prose says 80–200 K and 50–300 cm−1 using a 633 nm pump, but PL/Raman overlap prevents useful measurements above 190 K; Figure S2 actually captions 80–190 K. Preserve the attempted range and displayed range separately.','low-frequency Raman',[('prose temperature interval','80–200','K'),('displayed temperature interval','80–190','K'),('Raman shift interval','50–300','cm-1'),('pump wavelength','633','nm'),('overlap threshold','>190','K')],'C2 G5','reported_acquisition'),
('raman-observation','si',6,'Raman discussion continued p7','Raman phase interpretation','Peaks around 120 and 250 cm−1 are assigned to I–Pb–I stretching and FA+ vibrations by comparison to cited studies. The 120 cm−1 peak shifts blue from 80 to 140 K then red above 140 K. FWHM is described as constant from 80 to 130 K with an abrupt change near 140 K. The prose mistakenly calls the Raman graphic Figure S1; its actual caption is S2.','current Raman observation',[('inorganic mode','120','cm-1'),('FA mode','250','cm-1'),('constant-width interval','80–130','K'),('abrupt-change temperature','~140','K')],'C1 G5','reported_measurement_and_interpretation'),
('raman-reference','si',6,'Raman literature comparison','Prior Raman ambiguity','Prior assignments of 111 cm−1 to δ and 135 cm−1 to α are contrasted with a study assigning 135 cm−1 to laser-induced PbO2 degradation, and reports of 96/111 cm−1 for α. These are cited contexts, not measured current PbO2 or δ contamination. Reference titles for some FA-mode comparisons concern methylammonium perovskites; preserve the stated comparison without validating an exact mode identity.','literature Raman context',[('prior delta mode','111','cm-1'),('disputed prior alpha/PbO2 mode','135','cm-1'),('alternative prior alpha mode1','96','cm-1'),('alternative prior alpha mode2','111','cm-1')],'G6','literature_context'),
('thermal-stability','si',9,'Figure S3','PL stability at 350 K','Figure S3 compares the 300 K spectrum with 350 K spectra at 0, 30, 60, 90, 120, 150, 180 and 210 min. The normalized intensity fit is PL_Intensity(t) = −0.026(t) + 1, with t in hours. This is a slight observed decline despite the main description highly stable; no absolute PL quantum yield is provided.','350K aging optical test',[('reference temperature label','300','K'),('aging temperature','350','K'),('last spectral time','210','min'),('spectral increment','30','min'),('normalized slope','-0.026','h-1'),('normalized intercept','1','dimensionless')],'G3 G5','reported_measurement_and_source_calculation'),
('cited-cell-gamma','main',6,'Scheme 1 discussion citing reference15','Gamma reference cell','The source quotes γ tetragonal P4/mbm, a = b = 8.88 Å and c = 6.28 Å, citing reference 15. These are external reference parameters used in a conceptual phase scheme, not a current QD cell refinement.','cited gamma bulk structure',[('a','8.88','angstrom'),('b','8.88','angstrom'),('c','6.28','angstrom')],'C4 G4 G6','literature_structure_context'),
('cited-cell-beta','main',6,'Scheme 1 discussion citing reference15','Beta reference cell','The source quotes β tetragonal P4/mbm, a = b = 8.92 Å and c = 6.33 Å. Both tetragonal phases use the same printed group symbol; no corrected group, atomic positions or occupancy is reconstructed.','cited beta bulk structure',[('a','8.92','angstrom'),('b','8.92','angstrom'),('c','6.33','angstrom')],'G4 G6','literature_structure_context'),
('cited-cell-alpha','main',6,'Scheme 1 discussion','Alpha reference cell','The source prints cubic Pm3m with a = b = c = 6.36 Å. The symbol is retained as printed without silently adding an overbar; the paper provides no atom positions or CIF. It is not bound as an exact measured QD model.','cited alpha bulk structure',[('a','6.36','angstrom'),('b','6.36','angstrom'),('c','6.36','angstrom')],'C4 G4 G6','literature_structure_context'),
('scheme-model','main',6,'Scheme 1 and related discussion','Phase and emission model','The scheme shows γ-tetragonal to β-tetragonal at 140 K, α-cubic at 250 K, PL enhancement through 350 K, then an expanded α schematic. Facet-dependent trap suppression, strain relief, exciton delocalization and bright-state activation are explanatory hypotheses. Source-drawn atomic-looking icons do not provide recoverable sample coordinates.','author conceptual structure-property model',[],'G4','author_interpretation'),
('literature-transition','main',5,'Table S1 comparison','Prior transition comparison','The main compares the current 250 K β→α assignment with bulk transition near 285 K, attributing the difference to uniformity and lower defects. Table S1 preserves distinct reports, sample forms and methods, including missing β→α cells; no blank is imputed as a negative result.','literature comparison',[('main bulk comparison','~285','K'),('current beta-alpha','250','K')],'C3 G6','literature_context'),
('washing-photo','si',5,'Figure S1','Washing-waste photograph','Three washing-waste vials are labeled OAm:OA 1:2, 1:3 and 1:4. The caption identifies substantial QD solubility/partial dissolution for 1:4. Waste is distinct from the retained product supernatant; no quantitative dissolved mass is measured.','washing waste',[],'G3','reported_observation'),
('source-notes','main',7,'Notes, acknowledgments and abbreviations','Publication notes','The authors declare no competing financial interest. Funding, affiliations and abbreviations are retained in the private source payload; the source declares experimental methods, Raman, transition comparison and thermal stability SI. No extra crystallographic or raw instrumental attachment is supplied in this bundle.','source notes',[],'G4 G6','bibliographic'),
('background','main',1,'Introduction continued p2','Literature and motivation','The source contrasts photoactive black α and photo-inactive yellow δ FAPbI3, discusses grain-boundary instability in bulk films, and cites additives, encapsulation, interfaces and prior QDs. These literature devices, micrometer grains and theoretical mechanisms are not current synthesis variants or validated device performance.','cited background',[],'G6','literature_context'),
('conclusion','main',6,'Conclusion','Source conclusion','The source concludes that optimized ligand, purification and growth conditions yield approximately 10.4 nm QDs, roughly 150 ns lifetimes and low-index diffraction features, with γ→β→α optical/Raman transitions and PL enhancement up to 350 K. Application to solar cells is prospective; this study supplies no fabricated solar-cell recipe or measured device efficiency.','author conclusion',[],'G3 G4','author_interpretation'),
]

CONFLICTS=[
('C1','SI figure and page references','SI p6–7 calls Raman Figure S1 although actual Raman is Figure S2; S1 is washing waste. Index gives Table S1 on S7 and Figure S3 on S8, but actual pages are S8/S9.'),
('C2','Raman intended and shown temperature scope','SI prose states80–200 K but reports overlap above190 K; Figure S2 caption is80–190 K. These are separate stated ranges.'),
('C3','Table S1 cited specimen versus reference title','Table S1 row9 labels FAPbI3 nanocrystals15.6 nm and cites SI reference14, whose title concerns methylammonium lead iodide. The citation/sample mismatch remains unresolved; no cross-paper identity repair.'),
('C4','Local fringe, reference cell and symmetry notation','TEM labels6.38 Å as(002), while the source quotes cubic a6.36 Å. The standard cubic spacing relation would differ; retain both without changing the index or promoting a reference cell to a measured QD cell. The cubic group is printed Pm3m and retained literally.'),
('C5','Instrument/equation typography','SI prints average-lifetime equation number(2) without a supplied equation(1), and calls the temperature stage a hostage module. Literal source wording is retained; no missing equation or hardware specification is reconstructed.'),
]
GAPS=[
('G1','Material identity and grade limits','PbI2 purity/supplier absent; OAm70% and ODE>90% are technical source grades, without composition/isomer assays. Hexane is not specified as n-hexane.'),
('G2','Preparation and workup missingness','Vacuum pressure, ramps, stirring, absolute wash volumes, hexane volume, repetition count, final stock volume/concentration, growth dwell, injection/cooling rates and numeric room temperature are missing.'),
('G3','Specimen and outcome limits','Factor-series panels have specified conditions but no complete replicate or exact cross-technique physical-batch map. Final dispersions have unreported concentration/storage. No isolated yield, absolute PLQY or measured solar-cell efficiency is supplied.'),
('G4','Atomic and phase-model boundary','No measured QD CIF/coordinates, occupancy refinement, SAED dataset or exact training pair. Source/cited phase cells and conceptual drawings are separate from QD measurements; no surface ligand/particle geometry is inferred.'),
('G5','Acquisition and raw-data limits','Measurement physical form/atmosphere/mounting, thermal dwell/ramp, laser power, XRD settings, TEM preparation/counts and full fit coefficients/errors are missing. Curves are not digitized or refitted.'),
('G6','Cited work not retrieved','All cited studies remain citation-level context. Literature table rows and bulk lattice values are retained as quoted, without downloading original references or validating their full source content.'),
]
